import java.io.File;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Map;
import java.util.HashMap;

public class GenerateAuthFiles {
    public static void main(String[] args) throws Exception {
        String basePath = "d:/future tech/backend/src/main/java/com/futuretech";

        Map<String, String> files = new HashMap<>();

        // DTOs
        files.put(basePath + "/dto/AuthRequest.java", "package com.futuretech.dto;\nimport lombok.Data;\n@Data\npublic class AuthRequest {\n    private String email;\n    private String password;\n}\n");
        files.put(basePath + "/dto/AuthResponse.java", "package com.futuretech.dto;\nimport lombok.AllArgsConstructor;\nimport lombok.Data;\n@Data @AllArgsConstructor\npublic class AuthResponse {\n    private String token;\n    private String userType;\n    private String message;\n}\n");
        files.put(basePath + "/dto/RegisterRequest.java", "package com.futuretech.dto;\nimport lombok.Data;\n@Data\npublic class RegisterRequest {\n    private String fullName;\n    private String email;\n    private String password;\n    private String institutionName;\n}\n");
        files.put(basePath + "/dto/MessageResponse.java", "package com.futuretech.dto;\nimport lombok.AllArgsConstructor;\nimport lombok.Data;\n@Data @AllArgsConstructor\npublic class MessageResponse {\n    private String message;\n}\n");

        // Security
        files.put(basePath + "/security/CustomUserDetails.java", "package com.futuretech.security;\nimport com.futuretech.entity.User;\nimport org.springframework.security.core.GrantedAuthority;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.core.userdetails.UserDetails;\nimport java.util.Collection;\nimport java.util.Collections;\n\npublic class CustomUserDetails implements UserDetails {\n    private final User user;\n    public CustomUserDetails(User user) { this.user = user; }\n    public User getUser() { return user; }\n    @Override public Collection<? extends GrantedAuthority> getAuthorities() {\n        return Collections.singletonList(new SimpleGrantedAuthority(\"ROLE_\" + user.getUserType().name()));\n    }\n    @Override public String getPassword() { return user.getPasswordHash(); }\n    @Override public String getUsername() { return user.getEmail(); }\n    @Override public boolean isAccountNonExpired() { return true; }\n    @Override public boolean isAccountNonLocked() { return user.getIsActive(); }\n    @Override public boolean isCredentialsNonExpired() { return true; }\n    @Override public boolean isEnabled() { return user.getIsActive(); }\n}\n");

        files.put(basePath + "/security/CustomUserDetailsService.java", "package com.futuretech.security;\nimport com.futuretech.entity.User;\nimport com.futuretech.repository.UserRepository;\nimport lombok.RequiredArgsConstructor;\nimport org.springframework.security.core.userdetails.UserDetails;\nimport org.springframework.security.core.userdetails.UserDetailsService;\nimport org.springframework.security.core.userdetails.UsernameNotFoundException;\nimport org.springframework.stereotype.Service;\n\n@Service\n@RequiredArgsConstructor\npublic class CustomUserDetailsService implements UserDetailsService {\n    private final UserRepository userRepository;\n    @Override\n    public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException {\n        User user = userRepository.findByEmail(username)\n                .orElseThrow(() -> new UsernameNotFoundException(\"User not found with email: \" + username));\n        return new CustomUserDetails(user);\n    }\n}\n");

        files.put(basePath + "/security/JwtUtil.java", "package com.futuretech.security;\nimport io.jsonwebtoken.Claims;\nimport io.jsonwebtoken.Jwts;\nimport io.jsonwebtoken.SignatureAlgorithm;\nimport io.jsonwebtoken.security.Keys;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.security.core.userdetails.UserDetails;\nimport org.springframework.stereotype.Component;\nimport java.security.Key;\nimport java.util.Date;\nimport java.util.function.Function;\n\n@Component\npublic class JwtUtil {\n    @Value(\"${app.jwt.secret}\") private String secret;\n    @Value(\"${app.jwt.expiration-ms}\") private long jwtExpirationMs;\n\n    private Key getSigningKey() { return Keys.hmacShaKeyFor(secret.getBytes()); }\n\n    public String extractUsername(String token) { return extractClaim(token, Claims::getSubject); }\n\n    public Date extractExpiration(String token) { return extractClaim(token, Claims::getExpiration); }\n\n    public <T> T extractClaim(String token, Function<Claims, T> claimsResolver) {\n        final Claims claims = extractAllClaims(token);\n        return claimsResolver.apply(claims);\n    }\n\n    private Claims extractAllClaims(String token) {\n        return Jwts.parserBuilder().setSigningKey(getSigningKey()).build().parseClaimsJws(token).getBody();\n    }\n\n    private Boolean isTokenExpired(String token) { return extractExpiration(token).before(new Date()); }\n\n    public String generateToken(UserDetails userDetails) {\n        return Jwts.builder().setSubject(userDetails.getUsername())\n                .setIssuedAt(new Date(System.currentTimeMillis()))\n                .setExpiration(new Date(System.currentTimeMillis() + jwtExpirationMs))\n                .signWith(getSigningKey(), SignatureAlgorithm.HS256).compact();\n    }\n\n    public Boolean validateToken(String token, UserDetails userDetails) {\n        final String username = extractUsername(token);\n        return (username.equals(userDetails.getUsername()) && !isTokenExpired(token));\n    }\n}\n");

        files.put(basePath + "/security/JwtAuthenticationFilter.java", "package com.futuretech.security;\nimport jakarta.servlet.FilterChain;\nimport jakarta.servlet.ServletException;\nimport jakarta.servlet.http.HttpServletRequest;\nimport jakarta.servlet.http.HttpServletResponse;\nimport lombok.RequiredArgsConstructor;\nimport org.springframework.security.authentication.UsernamePasswordAuthenticationToken;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.security.core.userdetails.UserDetails;\nimport org.springframework.security.web.authentication.WebAuthenticationDetailsSource;\nimport org.springframework.stereotype.Component;\nimport org.springframework.web.filter.OncePerRequestFilter;\nimport java.io.IOException;\n\n@Component\n@RequiredArgsConstructor\npublic class JwtAuthenticationFilter extends OncePerRequestFilter {\n    private final JwtUtil jwtUtil;\n    private final CustomUserDetailsService userDetailsService;\n\n    @Override\n    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain filterChain) throws ServletException, IOException {\n        final String authHeader = request.getHeader(\"Authorization\");\n        String username = null;\n        String jwt = null;\n\n        if (authHeader != null && authHeader.startsWith(\"Bearer \")) {\n            jwt = authHeader.substring(7);\n            username = jwtUtil.extractUsername(jwt);\n        }\n\n        if (username != null && SecurityContextHolder.getContext().getAuthentication() == null) {\n            UserDetails userDetails = this.userDetailsService.loadUserByUsername(username);\n            if (jwtUtil.validateToken(jwt, userDetails)) {\n                UsernamePasswordAuthenticationToken authToken = new UsernamePasswordAuthenticationToken(\n                        userDetails, null, userDetails.getAuthorities());\n                authToken.setDetails(new WebAuthenticationDetailsSource().buildDetails(request));\n                SecurityContextHolder.getContext().setAuthentication(authToken);\n            }\n        }\n        filterChain.doFilter(request, response);\n    }\n}\n");

        files.put(basePath + "/config/SecurityConfig.java", "package com.futuretech.config;\nimport com.futuretech.security.JwtAuthenticationFilter;\nimport lombok.RequiredArgsConstructor;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.security.authentication.AuthenticationManager;\nimport org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;\nimport org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;\nimport org.springframework.security.config.annotation.web.builders.HttpSecurity;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer;\nimport org.springframework.security.config.http.SessionCreationPolicy;\nimport org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;\nimport org.springframework.security.crypto.password.PasswordEncoder;\nimport org.springframework.security.web.SecurityFilterChain;\nimport org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;\n\n@Configuration\n@EnableWebSecurity\n@EnableMethodSecurity\n@RequiredArgsConstructor\npublic class SecurityConfig {\n    private final JwtAuthenticationFilter jwtAuthFilter;\n\n    @Bean\n    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {\n        http.csrf(AbstractHttpConfigurer::disable)\n            .authorizeHttpRequests(auth -> auth\n                .requestMatchers(\"/api/auth/**\").permitAll()\n                .requestMatchers(\"/api/admin/**\").hasRole(\"ADMIN\")\n                .requestMatchers(\"/api/student/**\").hasRole(\"STUDENT\")\n                .anyRequest().authenticated()\n            )\n            .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))\n            .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class);\n        return http.build();\n    }\n\n    @Bean\n    public PasswordEncoder passwordEncoder() { return new BCryptPasswordEncoder(); }\n\n    @Bean\n    public AuthenticationManager authenticationManager(AuthenticationConfiguration config) throws Exception {\n        return config.getAuthenticationManager();\n    }\n}\n");

        // Service
        files.put(basePath + "/service/AuthService.java", "package com.futuretech.service;\nimport com.futuretech.dto.AuthRequest;\nimport com.futuretech.dto.AuthResponse;\nimport com.futuretech.dto.MessageResponse;\nimport com.futuretech.dto.RegisterRequest;\n\npublic interface AuthService {\n    MessageResponse registerStudent(RegisterRequest request);\n    AuthResponse login(AuthRequest request);\n}\n");

        files.put(basePath + "/service/impl/AuthServiceImpl.java", "package com.futuretech.service.impl;\nimport com.futuretech.dto.*;\nimport com.futuretech.entity.*;\nimport com.futuretech.entity.enums.*;\nimport com.futuretech.repository.*;\nimport com.futuretech.security.JwtUtil;\nimport com.futuretech.service.AuthService;\nimport lombok.RequiredArgsConstructor;\nimport org.springframework.security.authentication.AuthenticationManager;\nimport org.springframework.security.authentication.UsernamePasswordAuthenticationToken;\nimport org.springframework.security.core.userdetails.UserDetails;\nimport org.springframework.security.core.userdetails.UserDetailsService;\nimport org.springframework.security.crypto.password.PasswordEncoder;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\nimport java.util.UUID;\n\n@Service\n@RequiredArgsConstructor\npublic class AuthServiceImpl implements AuthService {\n    private final UserRepository userRepository;\n    private final StudentRepository studentRepository;\n    private final InstitutionRepository institutionRepository;\n    private final PasswordEncoder passwordEncoder;\n    private final AuthenticationManager authenticationManager;\n    private final JwtUtil jwtUtil;\n    private final UserDetailsService userDetailsService;\n\n    @Override\n    @Transactional\n    public MessageResponse registerStudent(RegisterRequest request) {\n        if (userRepository.findByEmail(request.getEmail()).isPresent()) {\n            throw new RuntimeException(\"Email is already registered.\");\n        }\n\n        User user = User.builder()\n                .name(request.getFullName())\n                .email(request.getEmail())\n                .passwordHash(passwordEncoder.encode(request.getPassword()))\n                .userType(UserType.STUDENT)\n                .isActive(true)\n                .build();\n        user = userRepository.save(user);\n\n        Institution tempInstitution = new Institution();\n        tempInstitution.setInstitutionName(request.getInstitutionName());\n        tempInstitution.setInstitutionType(InstitutionType.COLLEGE); // Default to college for now\n        tempInstitution = institutionRepository.save(tempInstitution);\n\n        Student student = Student.builder()\n                .user(user)\n                .studentCode(\"FT-\" + UUID.randomUUID().toString().substring(0,8).toUpperCase())\n                .firstName(request.getFullName())\n                .institution(tempInstitution)\n                .status(StudentStatus.PENDING_APPROVAL)\n                .profileStatus(ProfileStatus.INCOMPLETE)\n                .build();\n        studentRepository.save(student);\n\n        // TODO: Send Email (Phase 9)\n\n        return new MessageResponse(\"Registration Successful. Please wait for Admin approval.\");\n    }\n\n    @Override\n    public AuthResponse login(AuthRequest request) {\n        authenticationManager.authenticate(new UsernamePasswordAuthenticationToken(request.getEmail(), request.getPassword()));\n        User user = userRepository.findByEmail(request.getEmail()).orElseThrow(() -> new RuntimeException(\"User not found\"));\n\n        if (user.getUserType() == UserType.STUDENT) {\n            Student student = studentRepository.findByUserId(user.getId()).orElseThrow(() -> new RuntimeException(\"Student profile not found\"));\n            if (student.getStatus() != StudentStatus.APPROVED && student.getStatus() != StudentStatus.ACTIVE) {\n                throw new RuntimeException(\"Account is not approved yet. Status: \" + student.getStatus());\n            }\n        }\n\n        UserDetails userDetails = userDetailsService.loadUserByUsername(request.getEmail());\n        String token = jwtUtil.generateToken(userDetails);\n\n        return new AuthResponse(token, user.getUserType().name(), \"Login successful\");\n    }\n}\n");

        // Controller
        files.put(basePath + "/controller/AuthController.java", "package com.futuretech.controller;\nimport com.futuretech.dto.AuthRequest;\nimport com.futuretech.dto.AuthResponse;\nimport com.futuretech.dto.MessageResponse;\nimport com.futuretech.dto.RegisterRequest;\nimport com.futuretech.service.AuthService;\nimport lombok.RequiredArgsConstructor;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.*;\n\n@RestController\n@RequestMapping(\"/api/auth\")\n@RequiredArgsConstructor\npublic class AuthController {\n    private final AuthService authService;\n\n    @PostMapping(\"/register\")\n    public ResponseEntity<MessageResponse> register(@RequestBody RegisterRequest request) {\n        return ResponseEntity.ok(authService.registerStudent(request));\n    }\n\n    @PostMapping(\"/login\")\n    public ResponseEntity<AuthResponse> login(@RequestBody AuthRequest request) {\n        return ResponseEntity.ok(authService.login(request));\n    }\n}\n");
        
        // Seeder (for Default Admin)
        files.put(basePath + "/config/DataSeeder.java", "package com.futuretech.config;\nimport com.futuretech.entity.User;\nimport com.futuretech.entity.enums.UserType;\nimport com.futuretech.repository.UserRepository;\nimport lombok.RequiredArgsConstructor;\nimport org.springframework.boot.CommandLineRunner;\nimport org.springframework.security.crypto.password.PasswordEncoder;\nimport org.springframework.stereotype.Component;\n\n@Component\n@RequiredArgsConstructor\npublic class DataSeeder implements CommandLineRunner {\n    private final UserRepository userRepository;\n    private final PasswordEncoder passwordEncoder;\n\n    @Override\n    public void run(String... args) throws Exception {\n        if (userRepository.findByEmail(\"admin@futuretech.com\").isEmpty()) {\n            User admin = User.builder()\n                    .name(\"Future Tech Admin\")\n                    .email(\"admin@futuretech.com\")\n                    .passwordHash(passwordEncoder.encode(\"admin123\"))\n                    .userType(UserType.ADMIN)\n                    .isActive(true)\n                    .build();\n            userRepository.save(admin);\n            System.out.println(\"Default Admin created: admin@futuretech.com / admin123\");\n        }\n    }\n}\n");

        for (Map.Entry<String, String> entry : files.entrySet()) {
            Files.write(Paths.get(entry.getKey()), entry.getValue().getBytes());
        }
        System.out.println("Generated Auth files successfully.");
    }
}
